from __future__ import annotations

import logging
import os
from pathlib import Path
from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError
from robot.running.model import TestSuite, TestCase

from .context_filter import context
from .jsonformatter import JsonFormatter

AGENT_ROBOT_LOGDIR = "/home/ute/test_results"
AGENT_ROBOT_LOGGERS_NAMES = "root"

DEFAULT_FORMATTER = JsonFormatter()

_logger = logging.getLogger(__name__)
_logger.addHandler(logging.NullHandler())


class LoggingConfigurator:

    ROBOT_LISTENER_API_VERSION = 3

    def start_suite(self, suite: TestSuite, result) -> None:
        try:
            logdir = self._get_log_directory()
            loggers_names = self._get_loggers_names()
            self._set_up_loggers(
                formatter=DEFAULT_FORMATTER, logdir=logdir, logger_names=loggers_names
            )
        except Exception as e:
            logging.error(str(e))

        context.update_execution_id(os.getenv('CM_EXECUTION_ID'))
        context.update_username(os.getenv("CM_USERNAME"))
        context.update_suite_name(suite.name)
        context.update_suite_path(os.getenv("CM_TEST_PATH"))
        context.update_repository(os.getenv("CM_ARTIFACTS"))

    def start_test(self, test: TestCase, result) -> None:
        context.update_test_case_name(test.name)

    def _set_up_loggers(self, logger_names: set[str], logdir: str, formatter: logging.Formatter) -> None:
        if not logger_names:
            _logger.info("No loggers names provided, skipping loggers setup")
            return

        Path(logdir).mkdir(parents=True, exist_ok=True)

        for logger in [logging.getLogger(name) for name in logger_names]:
            handler = self._create_file_handler(logdir, logger.name, formatter)
            handler.addFilter(context)
            logger.addHandler(handler)

    @staticmethod
    def _create_file_handler(
        logdir: str,
        logger_name: str,
        formatter: logging.Formatter
    ) -> logging.FileHandler:
        logger_filename = f"radar_{logger_name}.log"
        file_handler = logging.FileHandler(Path(logdir) / logger_filename, delay=True)
        file_handler.setFormatter(formatter)
        return file_handler

    @staticmethod
    def _get_loggers_names() -> set[str]:
        return {AGENT_ROBOT_LOGGERS_NAMES}  # Impact Radar logs only from the root logger

    @staticmethod
    def _get_log_directory() -> str:
        try:
            log_dir = BuiltIn().get_variable_value("${AGENT_ROBOT_LOGDIR}")
            log_dir = log_dir or AGENT_ROBOT_LOGDIR
        except RobotNotRunningError:
            log_dir = AGENT_ROBOT_LOGDIR
        _logger.info(f"Log directory: {log_dir}")
        return log_dir
